"""The mutation list of `tools/ratings.py` (PROCESSES.md P18 step 4, kept for the engine as for firmware).

`make mutate-ratings` runs `workcenter mutate . --mutations tests/ratings_mutations.py`: each change below,
in its own copy of the paths COPY names, must fail TEST. The command reads the 3 names as literals and
runs nothing of this file. `tests/test_ratings_mutations.py` holds every anchor to the engine in `make
verify`: an edit of the engine that moves an anchor fixes the anchor in the same commit (P18 step 6).

A name is the reviewer's id of 2026-11-17 and the part of the engine it changes. The reviewer's 431
changes were written against an older engine; each is anchored here to the text it changes now.
EQUIVALENT names the changes no test can catch, each with the reason; GONE the ones whose code was
rewritten since. FU01 to FU21 change the rule by rating that a fuse's current is held to, and the
rule that grants a kind no share.
"""

TEST = (
    "${PYTHON:-python3} -m pytest tests/test_ratings.py tests/test_ratings_edges.py tests/test_ratings_fuse.py"
    " -x -q -p no:cacheprovider"
)
COPY = ["pyproject.toml", "tools", "rules", "tests"]

EQUIVALENT = {
    "FC03": "`ambient <= knee` to `<`: at the knee the line gives max + (floor - max) x 0 = max",
    "FO02": "a pattern's 2 to 1: with a part number a symbol's entry ranks 0, without one no pattern matches",
    "JG10": "`<=` to `<` in ratio(): the 2 differ for a stress exactly EPS (1e-9) past its limit alone",
    "JG44": "the drain current's note names its part, and the loop visits each part 1 time",
    "LV07": "`fail + left` to `left` in verdict(): `fail` is 0 there, the line before returned otherwise",
    "LV12": "markdown()'s verdict without `strict`: the text of verdict() does not depend on it",
    "LV16": "markdown()'s lines(report) for lines(report, 0): its first line is the counts at any limit",
    "NS11": "`model.ohms is not None` to False: a model with ohms has `quiet` None, which is silent too",
    "NS43": "`if node in span` to True for `held`: `held` is read under `if node in span` alone",
    "NS46": "min(low, 0.0) of a solved tap: every span holds 0 V, so its low is 0 or under already",
    "PV08": "`after and not multiplier`: `(\\d+)` is greedy, and leaves no digits to `after` with no prefix",
    "PV12": "`decimals or after` to `after or decimals`: the line before returns when both are set",
}
GONE = {
    "NS36": "net_spans tests `stiff` in 1 place now, as NS35",
    "FA06": "_facts checks 1 tuple of ratings, RATED, as FA05",
    "JG08": "judge() reads `accepted` in 1 loop after every finding",
    "JG48": "judge() reads `accepted` in 1 loop after every finding",
    "JG57": "seen_by() no longer tests a part's drives and the rails",
    "JG58": "seen_by() no longer tests a part's drives and the rails",
    "IC29": "the merged line prints the 2 ends unrounded",
    "JR17": "_judge_rail's load has no `far` net",
}

